class Vehicle:
    def __init__(self, make: str):
        self.make = make
        self.wheels = 4

    def info(self) -> str:
        return f"{self.make} with {self.wheels} wheels"


class ElectricCar(Vehicle):
    def __init__(self, make: str, battery_kwh: int):
        super().__init__(make)
        self.battery_kwh = battery_kwh

    def range_km(self) -> int:
        return self.battery_kwh * 6


make = input().strip()
battery = int(input())
van = Vehicle("Ford")
car = ElectricCar(make, battery)
print(van.info())
print(car.info())
print(f"Battery: {car.battery_kwh} kWh")
print(f"Range: {car.range_km()} km")

