import math


class Shape:
    def __init__(self, name: str):
        self.name = name

    def area(self) -> float:
        return 0.0

    def describe(self) -> str:
        return f"{self.name}: area {self.area():.2f}"


class Circle(Shape):
    def __init__(self, radius: float):
        super().__init__("Circle")
        self.radius = radius

    def area(self) -> float:
        return math.pi * self.radius ** 2


class Square(Shape):
    def __init__(self, side: float):
        super().__init__("Square")
        self.side = side

    def area(self) -> float:
        return self.side ** 2

    def describe(self) -> str:
        return super().describe() + f"\n  all 4 sides are {self.side}"


shapes = []
for _ in range(int(input())):
    kind, size = input().split()
    if kind == "circle":
        shapes.append(Circle(float(size)))
    else:
        shapes.append(Square(float(size)))

for shape in shapes:
    print(shape.describe())
    print(f"  is a Circle: {isinstance(shape, Circle)}")
print(f"Square is a Shape: {issubclass(Square, Shape)}")

