class Employee:
    def __init__(self, name: str, salary: int):
        self.name = name
        self.salary = salary

    def title(self) -> str:
        return self.name

    def pay(self) -> int:
        return self.salary


class Manager(Employee):
    def title(self) -> str:
        return super().title() + " (Manager)"

    def pay(self) -> int:
        return self.salary + 1000


class Engineer(Employee):
    def pay(self) -> int:
        return self.salary + 500


staff = []
for _ in range(int(input())):
    role, name, salary = input().split()
    if role == "manager":
        staff.append(Manager(name, int(salary)))
    elif role == "engineer":
        staff.append(Engineer(name, int(salary)))
    else:
        staff.append(Employee(name, int(salary)))

total = 0
managers = 0
for person in staff:
    pay = person.pay()
    print(f"{person.title()}: {pay}")
    total += pay
    if isinstance(person, Manager):
        managers += 1
print(f"Total: {total}")
print(f"Managers: {managers}")
print(f"Manager is an Employee: {issubclass(Manager, Employee)}")

