import math
from abc import ABC, abstractmethod


class Shape(ABC):
    @abstractmethod
    def area(self) -> float:
        pass

    def report(self) -> str:
        return f"{type(self).__name__}: {self.area():.2f}"


class Rectangle(Shape):
    def __init__(self, width: float, height: float):
        self.width = width
        self.height = height

    def area(self) -> float:
        return self.width * self.height


class Circle(Shape):
    def __init__(self, radius: float):
        self.radius = radius

    def area(self) -> float:
        return math.pi * self.radius ** 2


class Blob(Shape):
    pass


try:
    Shape()
except TypeError:
    print("cannot create Shape")

try:
    Blob()
except TypeError:
    print("cannot create Blob: area() is missing")

shapes = []
for _ in range(int(input())):
    match input().split():
        case ["rect", width, height]:
            shapes.append(Rectangle(float(width), float(height)))
        case ["circle", radius]:
            shapes.append(Circle(float(radius)))

total = 0.0
for shape in shapes:
    print(shape.report())
    total += shape.area()
print(f"Total area: {total:.2f}")

