from abc import ABC, abstractmethod


class PaymentMethod(ABC):
    @abstractmethod
    def pay(self, amount: float) -> str:
        pass

    def receipt(self, amount: float) -> str:
        return f"Receipt: {self.pay(amount)}"


class Card(PaymentMethod):
    def __init__(self, last4: str):
        self.last4 = last4

    def pay(self, amount: float) -> str:
        return f"paid {amount:.2f} with card ending {self.last4}"


class Cash(PaymentMethod):
    def pay(self, amount: float) -> str:
        return f"paid {amount:.2f} in cash"


class Crypto(PaymentMethod):
    pass


try:
    PaymentMethod()
except TypeError:
    print("cannot create PaymentMethod")

try:
    Crypto()
except TypeError:
    print("cannot create Crypto: pay() is missing")

payments = []
for _ in range(int(input())):
    match input().split():
        case ["card", last4, amount]:
            payments.append((Card(last4), float(amount)))
        case ["cash", amount]:
            payments.append((Cash(), float(amount)))

total = 0.0
for method, amount in payments:
    print(method.receipt(amount))
    total += amount
print(f"Total: {total:.2f}")
